using Microsoft.EntityFrameworkCore;
using VanderBeer.Api.Models;
namespace VanderBeer.Api.Data;
public class VanderBeerDbContext(DbContextOptions<VanderBeerDbContext> options):DbContext(options) {
 public DbSet<Categoria> Categorias=>Set<Categoria>(); public DbSet<Produto> Produtos=>Set<Produto>(); public DbSet<Cliente> Clientes=>Set<Cliente>(); public DbSet<Pedido> Pedidos=>Set<Pedido>(); public DbSet<ItemPedido> ItensPedido=>Set<ItemPedido>();
 protected override void OnModelCreating(ModelBuilder m) { m.Entity<Categoria>().HasIndex(x=>x.Nome).IsUnique(); m.Entity<Cliente>().HasIndex(x=>x.Cpf).IsUnique(); m.Entity<Cliente>().HasIndex(x=>x.Verificador).IsUnique(); m.Entity<Pedido>().HasIndex(x=>x.CodigoPedido).IsUnique(); m.Entity<Produto>().HasOne(x=>x.Categoria).WithMany(x=>x.Produtos).HasForeignKey(x=>x.CategoriaId).OnDelete(DeleteBehavior.Restrict); m.Entity<ItemPedido>().HasOne(x=>x.Produto).WithMany(x=>x.ItensPedido).HasForeignKey(x=>x.ProdutoId).OnDelete(DeleteBehavior.Restrict); m.Entity<Categoria>().HasData(new Categoria{Id=1,Nome="Cervejas"},new Categoria{Id=2,Nome="Refrigerantes"},new Categoria{Id=3,Nome="Águas"}); var data=new DateTime(2026,10,8,0,0,0,DateTimeKind.Utc); m.Entity<Produto>().HasData(new Produto{Id=1,Nome="Cerveja Pilsen 350 ml",Descricao="Cerveja leve e refrescante.",Preco=5.90m,Estoque=50,CategoriaId=1,DataCadastro=data},new Produto{Id=2,Nome="Cerveja IPA 500 ml",Descricao="Cerveja artesanal de amargor marcante.",Preco=14.90m,Estoque=25,CategoriaId=1,DataCadastro=data},new Produto{Id=3,Nome="Refrigerante Cola 2 L",Descricao="Refrigerante sabor cola.",Preco=10.50m,Estoque=40,CategoriaId=2,DataCadastro=data},new Produto{Id=4,Nome="Refrigerante Guaraná 2 L",Descricao="Refrigerante sabor guaraná.",Preco=9.90m,Estoque=40,CategoriaId=2,DataCadastro=data},new Produto{Id=5,Nome="Água mineral 500 ml",Descricao="Água mineral sem gás.",Preco=3.00m,Estoque=100,CategoriaId=3,DataCadastro=data},new Produto{Id=6,Nome="Água com gás 500 ml",Descricao="Água mineral gaseificada.",Preco=3.50m,Estoque=80,CategoriaId=3,DataCadastro=data}); }
}
